                        severity: Severity::Info,
                        byte_range: line_start..stmt.start_byte(),
                        line: pos.row + 1,
                        column: 1,
                        fix: Some(Fix::new(
                            line_start..stmt.start_byte(),
                            " ".repeat(expected_indent),
                        )),
