def replace_leading_doc(path, new_doc):
    with open(path) as f:
        lines = f.read().split('\n')
    i = 0
    while i < len(lines) and lines[i].startswith('//!'):
        i += 1
    # drop trailing empty line left by removed doc block, if any
    rest = lines[i:]
    if rest and rest[0].strip() == '':
        rest = rest[1:]
    new_src = new_doc + '\n' + '\n'.join(rest)
    if not new_src.endswith('\n'):
        new_src += '\n'
    with open(path, 'w') as f:
        f.write(new_src)
    return i

for path, doc in DOCS.items():
    removed = replace_leading_doc(path, doc)
    print(f"replaced {removed} doc lines in {path}")
