import { readFileSync } from 'node:fs'
const src = readFileSync('crates/mlt_rules/src/codegen/mod.rs','utf8')
const lines = src.split('\n')
const out = []
for (const ln of lines) {
  const m = ln.match(/^\s*\/\/!(.*)$/)
  if (!m) break
  out.push(m[1].replace(/^ /, ''))
}
const doc = out.join('\n')
console.log("=== raw docstring lines 3..12 ===")
console.log(doc.split('\n').slice(3,12).join('\n'))
const fmEnd = doc.split('\n').findIndex(l => l.trim() === '```mlt')
const kvs = {}
const docLines = doc.split('\n')
for (let j = fmEnd + 1; j < docLines.length; j++) {
  const l = docLines[j].trim()
  if (l === '```') break
  const m = l.match(/^([A-Za-z_]+)\s*=\s*(.+)$/)
  if (!m) continue
  let v = m[2].trim()
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1,-1)
  kvs[m[1]] = v
}
console.log("kv.fix =", JSON.stringify(kvs.fix))
console.log("computed fm.fix =", (kvs.fix ?? 'false') === 'true')
EOF
bun /tmp/opencode/dbg.mjs

